const TAG_HTML_TEMPLATE = `
<div style="font-family:'Mr Eaves XL Modern'; width:8.5cm; height:17cm; box-sizing:border-box; border-collapse:collapse;">
  <div style="width:100%; height:100%; box-sizing:border-box; display:flex; flex-direction:column; justify-content:space-between; padding:0.5cm; border:1px solid #e0dacf;">
    <div style="position:relative; width:100%; height:100%; box-sizing:border-box; display:flex; flex-direction:column; justify-content:space-between;">
      
      <div style="flex-grow:1;">
        <div style="font-size:42px; font-family:'Mr Eaves XL Modern Heavy','Mr Eaves XL Modern'; text-transform:uppercase; line-height:38px;">{{name}}</div>
        <div style="font-size:21px; font-family:'Mr Eaves XL Modern Bold'; line-height:1.4; height:0.8cm;">{{category}}</div>
        <div style="width:2cm; border-bottom:0.07cm solid #333; margin:0.13cm 0 0.2cm 0;"></div>

        {{#if isDiscountAvailable}}
          <!-- MRP (struck-through) -->
          <div style="display:inline-flex; align-items:center; position:relative; padding:0 4px;">
            <span style="font-family:'Rupee Foradian','Mr Eaves XL Modern Bold'; font-size:18px; margin-right:3px; display:inline-flex; align-items:center; margin-top:2px;">₹</span>
            <span style="font-family: 'Mr Eaves XL Modern Bold';font-size:24px; display:inline-flex; align-items:center; text-decoration: line-through;">{{formattedMrp}}</span>
          </div>

          <!-- Discounted price -->
          <div style="line-height: 1.2; display: flex; align-items: flex-end;">
            <span style="font-family:'Rupee Foradian','Mr Eaves XL Modern Modern','sans-serif'; font-size:20px; margin-right:3px; margin-bottom:4px;">₹</span>
            <span style="font-family: 'Mr Eaves XL Modern Bold';font-size:32px;">{{formattedEffectivePrice}}</span>
          </div>
        {{else}}
          <!-- Single price (no discount) -->
          <div style="line-height: 1.4; display: inline-flex; align-items: flex-end;">
            <span style="font-family:'Rupee Foradian','Mr Eaves XL Modern Modern','sans-serif'; font-size:32px; margin-right:3px; margin-bottom:7px;">₹</span>
            <span style="font-family: 'Mr Eaves XL Modern Bold';font-size:46px;">{{formattedMrp}}</span>
          </div>
        {{/if}}


        <div style="color:#777; font-size:14px; height:0.7cm; line-height:20px;">(Inclusive of all taxes)</div>

        <div style="height:auto;">
          {{#each attributes}}
            <div style="display:flex; gap:0.5cm; font-size:18px; line-height:22px; min-height:0.5cm; margin-bottom:6px;">
              <div style="flex:1;font-family:'Mr Eaves XL Modern Bold';">{{label}}</div>
              <div style="flex:1;">{{value}}</div>
            </div>
          {{/each}}
        </div>
      </div>

      <div style="clear:both; display:flex; align-items:flex-start; margin-top:0.5cm;">
        <div style="text-align:center; display:inline-block;">
          <img src="{{qrCode}}" alt="QR code" />
        </div>
        <div style="font-size:12px; text-align:left; margin-left:0.7cm; margin-top:1cm; width:112px; height:auto; line-height:17.15px;">
          Download our app & scan this QR code to know more
        </div>
      </div>

      <div style="position:absolute; bottom:0; right:0; left:0; transform:rotate(-90deg) translate(100%,0); transform-origin:right; color:#777; font-size:12px;">
        *Pieces on display are not for sale
      </div>

    </div>
  </div>
</div>

`;

